async function main() {
  console.log('=== 从product数据库恢复和茶时代门店数据 ===\n');

  // 1. 统计状态
  const servingCount = productStores.filter(s => s.business_status === '营业中').length;
  const pausedCount = productStores.filter(s => s.business_status === '暂停营业').length;

  console.log('1. 门店数据统计');
  console.log(`  总门店数: ${productStores.length} 家`);
  console.log(`  - 营业中: ${servingCount} 家`);
  console.log(`  - 暂停营业: ${pausedCount} 家`);

  // 2. 清空develop数据库中的和茶时代门店
  console.log('\n2. 清空develop数据库中的和茶时代门店');
  const { error: deleteError } = await devClient
    .from('stores')
    .delete()
    .eq('store_system', 'hecha');

  if (deleteError) {
    console.error('清空失败:', deleteError);
    process.exit(1);
  }

  console.log('  ✓ 清空完成');

  // 3. 批量插入门店数据
  console.log('\n3. 批量插入门店数据');
  let successCount = 0;
  let failedCount = 0;

  for (const store of productStores) {
    try {
      // 处理store_level：将空字符串转换为NULL
      const storeLevel = store.store_level === '' ? null : store.store_level;

      const { error } = await devClient.from('stores').insert({
        store_id: store.store_id,
        store_name: store.store_name,
        store_system: 'hecha',
        category: store.category,
        merchant_name: store.merchant_name,
        merchant_id: store.merchant_id,
        merchant_phone: store.merchant_phone,
        province: store.province,
        city: store.city,
        address: store.address,
        attach_status: store.attach_status,
        business_status: store.business_status,
        store_level: storeLevel,
        phone1: store.phone1,
        phone2: store.phone2,
        phone3: store.phone3,
      });

      if (error) {
        failedCount++;
        console.error(`  ✗ 失败 [${store.store_name}]:`, error.message);
      } else {
        successCount++;
        console.log(`  ✓ 成功 [${store.store_name}]`);
      }
    } catch (err) {
      failedCount++;
      console.error(`  ✗ 错误 [${store.store_name}]:`, err);
    }
  }

  console.log(`\n插入完成:`);
  console.log(`  成功: ${successCount} 家`);
  console.log(`  失败: ${failedCount} 家`);

  // 4. 验证最终数据
  console.log('\n4. 验证最终数据');
  const { data: finalStores, error: finalError } = await devClient
    .from('stores')
    .select('store_name, business_status')
    .eq('store_system', 'hecha')
    .order('business_status', { ascending: false }); // 营业中排前面

  if (finalError) {
    console.error('查询失败:', finalError);
    process.exit(1);
  }

  const finalServingCount = finalStores.filter(s => s.business_status === '营业中').length;
  const finalPausedCount = finalStores.filter(s => s.business_status === '暂停营业').length;

  console.log(`  develop数据库中和茶时代门店总数: ${finalStores.length} 家`);
  console.log(`  - 营业中: ${finalServingCount} 家`);
  console.log(`  - 暂停营业: ${finalPausedCount} 家`);

  if (finalStores.length === 155) {
    console.log('\n✅ 数据恢复成功，与product数据库一致（155家）');
  } else {
    console.log(`\n⚠️  数据数量不一致：期望155家，实际${finalStores.length}家`);
  }

  console.log('\n=== 处理完成 ===');
}

main().catch(console.error);
